<div class="card"><div class="card-header d-flex justify-content-between align-items-center"><h5 class="mb-0">Riwayat Pembayaran</h5><a id="btnExport" class="btn btn-success"><i class="ti ti-file-spreadsheet"></i> Ekspor Excel</a></div><div class="card-body">
<div class="row g-2 mb-3"><div class="col-lg-3"><input id="q" class="form-control" placeholder="No transaksi / nama / NIS"></div><div class="col-lg-2"><input id="awal" class="form-control tanggal-picker" placeholder="Tanggal awal dd-mm-yyyy" autocomplete="off"></div><div class="col-lg-2"><input id="akhir" class="form-control tanggal-picker" placeholder="Tanggal akhir dd-mm-yyyy" autocomplete="off"></div><div class="col-lg-2"><select id="metode" class="form-select"><option value="">Semua metode</option><?php foreach($metode as $m): ?><option value="<?= $m['id'] ?>"><?= html_escape($m['nama_metode']) ?></option><?php endforeach ?></select></div><div class="col-lg-2"><select id="filter_status_transaksi" class="form-select"><option value="">Semua status</option><option>Aktif</option><option>Dibatalkan</option></select></div><div class="col-lg-1 d-grid"><button id="cari" class="btn btn-primary"><i class="ti ti-search"></i></button></div></div>
<div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>No Transaksi</th><th>Tanggal</th><th>Siswa</th><th>Kelas</th><th>Metode</th><th class="text-end">Total</th><th>Petugas</th><th>Status</th><th>Aksi</th></tr></thead><tbody id="data"><tr><td colspan="9" class="empty-state">Memuat data...</td></tr></tbody></table></div></div></div>
<div class="modal fade" id="modalDetail"><div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Detail Transaksi</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="detailBody"></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Tutup</button></div></div></div></div>
<script>
$(function(){flatpickr('.tanggal-picker',{dateFormat:'d-m-Y',allowInput:true,disableMobile:true});let rows=[];const money=n=>'Rp'+Number(n||0).toLocaleString('id-ID');function params(){return {q:$('#q').val(),awal:$('#awal').val(),akhir:$('#akhir').val(),metode:$('#metode').val(),status:$('#filter_status_transaksi').val()}}function load(){$('#data').html('<tr><td colspan="9" class="empty-state">Memuat...</td></tr>');$.post('<?= base_url('riwayat_pembayaran/result') ?>',params(),r=>{rows=r||[];if(!rows.length)return $('#data').html('<tr><td colspan="9" class="empty-state">Tidak ada transaksi sesuai filter.</td></tr>');$('#data').html(rows.map(x=>`<tr><td><strong>${escapeHtml(x.no_transaksi)}</strong><br><small>${escapeHtml(x.waktu_transaksi)}</small></td><td>${escapeHtml(x.tanggal_transaksi)}</td><td>${escapeHtml(x.nama_siswa)}<br><small>${escapeHtml(x.nis)}</small></td><td>${escapeHtml(x.nama_kelas)}</td><td>${escapeHtml(x.nama_metode_pembayaran)}</td><td class="text-end fw-semibold">${money(x.total_pembayaran)}</td><td>${escapeHtml(x.nama_user)}</td><td><span class="badge bg-${x.status_transaksi==='Aktif'?'success':'danger'}-subtle text-${x.status_transaksi==='Aktif'?'success':'danger'}">${escapeHtml(x.status_transaksi)}</span></td><td><div class="action-buttons"><button class="btn btn-sm btn-primary detail" data-id="${x.id}">Detail</button><a target="_blank" href="<?= base_url('pembayaran/bukti/') ?>${x.id}" class="btn btn-sm btn-secondary">Cetak</a>${x.status_transaksi==='Aktif'?`<button class="btn btn-sm btn-danger batal" data-id="${x.id}">Batalkan</button>`:''}</div></td></tr>`).join(''))},'json').fail(ajaxError)}
 $('#cari').click(load);$('#q').keypress(e=>{if(e.which===13)load()});$('#btnExport').click(function(){let p=new URLSearchParams(params());this.href='<?= base_url('riwayat_pembayaran/export') ?>?'+p.toString()});
 $(document).on('click','.detail',function(){$.post('<?= base_url('riwayat_pembayaran/detail') ?>',{id:$(this).data('id')},r=>{if(r.result!=='true')return Swal.fire('Gagal',r.message,'error');let h=`<div class="row mb-3"><div class="col-md-6"><strong>${escapeHtml(r.header.no_transaksi)}</strong><br>${escapeHtml(r.header.tanggal_transaksi+' '+r.header.waktu_transaksi)}<br>${escapeHtml(r.header.nama_siswa)} (${escapeHtml(r.header.nis)})</div><div class="col-md-6 text-md-end">${escapeHtml(r.header.nama_kelas)}<br>${escapeHtml(r.header.nama_metode_pembayaran)}<br><strong>${money(r.header.total_pembayaran)}</strong></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Tagihan</th><th>Periode</th><th class="text-end">Sisa Sebelum</th><th class="text-end">Bayar</th><th class="text-end">Sisa Setelah</th></tr></thead><tbody>`+r.detail.map(d=>`<tr><td>${escapeHtml(d.nama_tagihan)}</td><td>${escapeHtml((d.nama_bulan||'')+' '+d.tahun)}</td><td class="text-end">${money(d.sisa_sebelum)}</td><td class="text-end">${money(d.nominal_bayar)}</td><td class="text-end">${money(d.sisa_setelah)}</td></tr>`).join('')+'</tbody></table></div>';if(r.pembatalan)h+=`<div class="alert alert-danger"><strong>Dibatalkan oleh ${escapeHtml(r.pembatalan.nama_user_pembatalan)}</strong><br>${escapeHtml(r.pembatalan.tanggal_pembatalan+' '+r.pembatalan.waktu_pembatalan)}<br>Alasan: ${escapeHtml(r.pembatalan.alasan_pembatalan)}</div>`;$('#detailBody').html(h);bootstrap.Modal.getOrCreateInstance(document.getElementById('modalDetail')).show()},'json')});
 $(document).on('click','.batal',function(){let id=$(this).data('id');Swal.fire({title:'Batalkan transaksi?',text:'Saldo setiap tagihan akan dikembalikan. Data transaksi tidak dihapus.',input:'textarea',inputLabel:'Alasan wajib',showCancelButton:true,confirmButtonText:'Konfirmasi Batalkan',confirmButtonColor:'#dc3545',preConfirm:v=>{if(!v.trim())Swal.showValidationMessage('Alasan wajib diisi');return v}}).then(v=>{if(!v.isConfirmed)return;$.post('<?= base_url('riwayat_pembayaran/batalkan') ?>',{id,alasan:v.value},r=>{Swal.fire(r.result==='true'?'Berhasil':'Gagal',r.message,r.result==='true'?'success':'error');if(r.result==='true')load()},'json').fail(ajaxError)})});load()});
</script>
